css:
/* A4, measured from the paper original. Top-level .print-format margins are the
   wkhtmltopdf page margins (Frappe reads them). */
.print-format {
    margin-top: 25mm;
    margin-bottom: 15mm;
    margin-left: 20mm;
    /* 2mm less than the layout margin; see the print padding below */
    margin-right: 18mm;
    padding: 0 !important;
    font-family: "Times New Roman", "Liberation Serif", serif;
    font-size: 10pt;
    line-height: 4.1mm;
    color: #000;
}
/* Frappe reads only the top-level rule above; don't apply it again inside the page.
   The 2mm right inset absorbs wkhtmltopdf drawing text slightly wider than it laid it out,
   which otherwise clips the last letters of full-width lines at the page margin. */
@media print {
    .print-format { margin: 0 !important; }
    .document-page { padding-right: 2mm; }
}
.document-page + .document-page { page-break-before: always; }
.document-page h3 { font-size: 10.5pt; font-weight: bold; text-align: center; line-height: 4.1mm; margin: 0 0 3mm; }
.document-page p { margin: 0; }
.document-page table { width: 169mm; margin-left: 1mm; border-collapse: collapse; table-layout: fixed; }
.document-page .grid td { border: 1px solid #000; padding: 1mm !important; vertical-align: middle !important; word-wrap: break-word; }
.document-page .grid tr { page-break-inside: avoid; }
.document-page .grid .sn { text-align: right; }
.document-page .grid .tall td { height: 8.2mm; }
.document-page .grid .heading { font-weight: bold; text-align: center; }
.document-page .grid td.bank { vertical-align: top !important; }
.document-page .value { white-space: pre-wrap; word-wrap: break-word; }
.document-page .proof .r { padding-left: 12.7mm; }
.document-page .proof .r .n { display: inline-block; width: 6.4mm; margin-left: -6.4mm; }
.document-page .declaration { font-size: 9pt; line-height: 3.6mm; margin-top: 2.3mm; }
.document-page .declaration table { width: 100%; margin: 0; }
.document-page .declaration td { padding: 0 !important; border: 0; vertical-align: top !important; }
.document-page .declaration td:first-child { width: 94mm; }
.document-page .declaration .skip { margin-top: 3.8mm; }
/* Browser preview: each page as an A4 sheet with the same margins. */
@media screen {
    .print-format {
        width: 210mm; max-width: none; min-height: 0;
        margin: 0 auto !important;
        background: transparent !important; box-shadow: none !important; border-radius: 0;
    }
    .document-page {
        box-sizing: border-box;
        width: 210mm;
        min-height: 297mm;
        padding: 25mm 20mm 15mm;
        margin: 0 auto 8mm;
        background: #fff;
        box-shadow: 0 1px 6px rgba(0, 0, 0, .25);
    }
}
